corporate_design.toad_component_blueprint:
canvas {
  size: 880px 560px;
  fill: #FDFCF7;
  font-family: "Barlow, serif";
}

>crust = #38220F;
>grain = #B45309;

rect #breadCard {
  at: center of canvas;
  size: 780px 460px;
  fill: #FFFFFF;
  stroke: >crust;
  stroke-width: 2px;
  radius: 8px;
}

text #breadHeader {
  at: top left of #breadCard offset 40px 40px;
  content: "BROTECHT // REINER NATURSAUERTEIG";
  font-size: 13px;
  font-weight: 700;
  color: >grain;
}

text #breadTitle {
  at: below #breadHeader offset 14px;
  content: "Roggenlaib aus dem Holzofen (48h Teigruhe)";
  font-size: 28px;
  font-weight: 700;
  color: >crust;
}
